### Configuration Examples by Environment

```json
// Development Environment - show all content
{
  "environments": {
    "dev": {
      "content": {
        "directories": [
          "decisions",
          "domains",
          "foundation",
          "guiding-principles",
          "job-descriptions",
          "rcas",
          "strategy",
          "training"
        ]
      },
      "navigation": {
        "directories": [
          "decisions",
          "domains",
          "foundation",
          "guiding-principles",
          "job-descriptions",
          "rcas",
          "strategy",
          "training"
        ]
      }
    }
  }
}
```

```json
// Staging Environment - exclude work in progress
{
  "environments": {
    "staging": {
      "content": {
        "directories": [
          "decisions",
          "domains",
          "foundation",
          "guiding-principles",
          "job-descriptions"
        ],
        "exclude_file_patterns": ["nav.json", "TEMPLATE.md", "*-draft.md", "*-wip.md"]
      },
      "navigation": {
        "exclude_file_patterns": [
          "LICENSE.md",
          "SECURITY.md",
          "TEMPLATE.md",
          "ai-repo-review.md",
          "*-draft.md"
        ]
      }
    }
  }
}
```

```json
// Production Environment - only completed content
{
  "environments": {
    "prod": {
      "content": {
        "directories": ["decisions", "domains", "foundation", "guiding-principles"]
      },
      "navigation": {
        "directories": ["decisions", "domains", "foundation", "guiding-principles"],
        "exclude_file_patterns": [
          "LICENSE.md",
          "SECURITY.md",
          "TEMPLATE.md",
          "ai-repo-review.md",
          "*-wip.md",
          "*-draft.md"
        ]
      }
    }
  }
}
```

