### 4. Content Processing (src/build.py)

The build module processes content and generates navigation:

```python
class NavigationBuilder:
    """Builds MkDocs navigation from repository content and nav.json files."""

    def build_navigation(self) -> List[Dict]:
        """Build complete navigation structure."""
        navigation = []

        # Discover content domains
        domains = self._discover_content_domains()

        # Process each domain
        for domain in sorted(domains, key=lambda d: d.get('order', 999)):
            if self.config.should_include_domain(domain['name']):
                nav_item = self._build_domain_navigation(domain)
                if nav_item:
                    navigation.append(nav_item)

        return navigation

    def _discover_content_domains(self) -> List[Dict]:
        """Discover all content domains with nav.json files."""
        domains = []
        root_path = Path(self.config.repository_root)

        for nav_file in root_path.glob('*/nav.json'):
            domain_path = nav_file.parent
            nav_config = self._load_nav_config(nav_file)

            domains.append({
                'name': domain_path.name,
                'path': domain_path,
                'config': nav_config,
                'order': nav_config.get('order', 999)
            })

        return domains

    def _build_domain_navigation(self, domain: Dict) -> Optional[Dict]:
        """Build navigation for a specific domain."""
        nav_config = domain['config']

        if not nav_config.get('enabled', True):
            return None

        sections = []
        for section_config in nav_config.get('sections', []):
            if self.config.should_include_section(section_config['title'].lower()):
                section_nav = self._build_section_navigation(domain, section_config)
                if section_nav:
                    sections.append(section_nav)

        return {
            nav_config['title']: sections
        } if sections else None
```
